package io.github.jesterportfolio.hearth.travel;

import io.github.jesterportfolio.hearth.session.*;
import io.github.jesterportfolio.hearth.quest.*;
import io.github.jesterportfolio.hearth.lifecycle.WorldLifecycle;
import io.github.jesterportfolio.hearth.persistence.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import net.kyori.adventure.text.Component;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.bukkit.WorldGuardPlugin;
import com.sk89q.worldguard.protection.flags.Flags;

/** 명시적으로 켠 격리 시험에서만 활성화합니다. 스마트폰/필드 명령으로 이동하지 않습니다. */
public final class PaperTravel implements Listener,AutoCloseable {
    private final JavaPlugin plugin;private final PaperSessionAdapter sessions;private final QuestJournal journal;private final Map<UUID,WorldLifecycle> worlds;private final Executor owner;public final FastTravel travel;public final TravelContent content;
    private final Map<UUID,Screen> screens=new HashMap<>();private final Map<UUID,Object> queries=new HashMap<>();private final Map<UUID,Port> ports=new HashMap<>();private final Map<String,Lease> leases=new HashMap<>();private boolean closed;
    private static final class Lease{final Chunk chunk;final boolean owned;int count=1;Lease(Chunk chunk,boolean owned){this.chunk=chunk;this.owned=owned;}}
    private final class Screen implements InventoryHolder{final Port port;final String source;final long generation;final Inventory inventory;final Map<Integer,String> targets=new HashMap<>();boolean busy;
        Screen(Port port,String source,List<FastTravel.Destination> choices,int page){this.port=port;this.source=source;generation=port.generation();inventory=Bukkit.createInventory(this,54,Component.text("시설 거점 이동"));var preview=previewDestinations(choices,page);inventory.setContents(preview.getContents());int slot=0;for(var row:FastTravel.page(choices,page))targets.put(slot++,row.id());if(choices.isEmpty()){var item=new ItemStack(Material.PAPER);item.editMeta(m->m.displayName(Component.text("이동 가능한 방문 거점이 없습니다")));inventory.setItem(22,item);}this.choices=choices;this.page=page;if(page>0)nav(45,"이전 페이지");if((page+1)*45<choices.size())nav(53,"다음 페이지");}
        final List<FastTravel.Destination> choices;final int page;private void nav(int slot,String text){var i=new ItemStack(Material.ARROW);i.editMeta(m->m.displayName(Component.text(text)));inventory.setItem(slot,i);}public Inventory getInventory(){return inventory;}}
    public PaperTravel(JavaPlugin plugin,PaperSessionAdapter sessions,QuestJournal journal,Map<UUID,WorldLifecycle> worlds,TravelContent content,Executor owner){
        if(!plugin.getConfig().getBoolean("fast-travel-verification-enabled")||!Boolean.getBoolean("hearth.verification.fastTravel"))throw new IllegalStateException("TRAVEL_ISOLATED_GATE");this.plugin=plugin;this.sessions=sessions;this.journal=journal;this.worlds=worlds;this.content=content;this.owner=owner;for(var s:content.stations().values())if(Material.matchMaterial(s.material())==null)throw new IllegalArgumentException("TRAVEL_MATERIAL");travel=new FastTravel(content,owner,PaperTravel::main);sessions.travelInventory((p,i)->i.getHolder() instanceof Screen s&&valid(p,s));for(UUID run:worlds.keySet())if(Bukkit.getWorld(worlds.get(run).mapping().physicalId())!=null)ensureRegions(run);Bukkit.getPluginManager().registerEvents(this,plugin);
    }
    public void ensureRegions(UUID run){main();var w=Objects.requireNonNull(Bukkit.getWorld(worlds.get(run).mapping().physicalId()));var manager=Objects.requireNonNull(WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(w)));for(var s:content.stations().values()){
        String id="hearth_travel_"+s.id();var p=s.facility();var point=com.sk89q.worldedit.math.BlockVector3.at((int)p.x(),(int)p.y(),(int)p.z());var old=manager.getRegion(id);
        if(old==null){var region=new com.sk89q.worldguard.protection.regions.ProtectedCuboidRegion(id,point,point);region.setPriority(30);region.setFlag(Flags.PASSTHROUGH,com.sk89q.worldguard.protection.flags.StateFlag.State.ALLOW);region.setFlag(Flags.INTERACT,com.sk89q.worldguard.protection.flags.StateFlag.State.ALLOW);manager.addRegion(region);}
        else if(!old.getMinimumPoint().equals(point)||!old.getMaximumPoint().equals(point)||old.getPriority()!=30||old.getFlag(Flags.INTERACT)!=com.sk89q.worldguard.protection.flags.StateFlag.State.ALLOW||old.getFlag(Flags.PASSTHROUGH)!=com.sk89q.worldguard.protection.flags.StateFlag.State.ALLOW)throw new IllegalStateException("TRAVEL_REGION_CONFLICT");
    }}
    private static void main(){if(!Bukkit.isPrimaryThread())throw new IllegalStateException("TRAVEL_MAIN_THREAD");}
    private static TravelContent.Point point(Location l){return new TravelContent.Point(l.getX(),l.getY(),l.getZ());}
    private boolean permitted(Player p,TravelContent.Station s){var w=WorldGuard.getInstance().getPlatform();var local=WorldGuardPlugin.inst().wrapPlayer(p);var loc=new Location(p.getWorld(),s.facility().x(),s.facility().y(),s.facility().z());return w.getSessionManager().hasBypass(local,BukkitAdapter.adapt(p.getWorld()))||w.getRegionContainer().createQuery().testState(BukkitAdapter.adapt(loc),local,Flags.INTERACT);}
    private final class Port implements FastTravel.Port{final Player player;final PlayerSessions.Session session;String lease;boolean locked;Port(Player player,PlayerSessions.Session s){this.player=player;session=s;}
        public ServerProgressAccess.Context context(){return session.context();}public Object session(){return session;}private WorldLifecycle worldState(){return Objects.requireNonNull(worlds.get(context().storyRunId()));}public UUID world(){return worldState().mapping().physicalId();}public long generation(){return worldState().generation();}public TravelContent.Point position(){return point(player.getLocation());}
        public boolean current(){return !closed&&sessions.prepared(player)==session&&player.getWorld().getUID().equals(world());}public boolean eligible(){return sessions.travelEligible(player,session)&&!player.isDead()&&player.getGameMode()==GameMode.SURVIVAL&&!player.isInsideVehicle();}
        public boolean access(TravelContent.Station s){return journal.travelAllowed(context(),s.place())&&permitted(player,s);}public boolean facility(TravelContent.Station s){var p=s.facility();return current()&&player.getWorld().isChunkLoaded(((int)p.x())>>4,((int)p.z())>>4)&&player.getWorld().getBlockAt((int)p.x(),(int)p.y(),(int)p.z()).getType().name().equals(s.material())&&permitted(player,s);}
        public void freeze(boolean frozen){if(frozen){sessions.freezeTravel(player,session,true);locked=true;}else if(locked){sessions.freezeTravel(player,session,false);locked=false;}}public CompletionStage<io.github.jesterportfolio.hearth.exploration.ExplorationView> read(){return journal.load(context(),session,this::current).thenApplyAsync(v->{journal.requireView(context(),v);return v.exploration();},owner);}public CompletionStage<Void> save(){return sessions.saveBoundary(player,session);}
        public CompletionStage<Void> prepare(TravelContent.Station s,BooleanSupplier valid){if(!valid.getAsBoolean())return CompletableFuture.failedFuture(new IllegalStateException("TRAVEL_STALE"));var w=player.getWorld();return w.getChunkAtAsync(((int)Math.floor(s.arrival().x()))>>4,((int)Math.floor(s.arrival().z()))>>4).thenAcceptAsync(chunk->{if(!valid.getAsBoolean()||!current())throw new IllegalStateException("TRAVEL_STALE");lease=chunk.getWorld().getUID()+"/"+chunk.getX()+"/"+chunk.getZ();var old=leases.get(lease);if(old==null)leases.put(lease,new Lease(chunk,chunk.addPluginChunkTicket(plugin)));else old.count++;if(!facility(s)||!safe(s))throw new IllegalStateException("TRAVEL_UNSAFE_DESTINATION");},owner);}
        private boolean safe(TravelContent.Station s){var w=player.getWorld();var p=s.arrival();var loc=new Location(w,p.x(),p.y(),p.z());if(!w.getWorldBorder().isInside(loc)||p.y()<=w.getMinHeight()||p.y()+2>=w.getMaxHeight())return false;for(double dx:new double[]{-0.3,0.3})for(double dz:new double[]{-0.3,0.3}){int x=(int)Math.floor(p.x()+dx),y=(int)Math.floor(p.y()),z=(int)Math.floor(p.z()+dz);if(!w.isChunkLoaded(x>>4,z>>4))return false;var floor=w.getBlockAt(x,y-1,z);var feet=w.getBlockAt(x,y,z);var head=w.getBlockAt(x,y+1,z);if(!io.github.jesterportfolio.hearth.combat.CombatPlayers.safeCells(floor.getType().name(),feet.getType().name(),head.getType().name(),floor.getType().isSolid(),feet.isPassable(),head.isPassable()))return false;}return true;}
        public CompletionStage<Boolean> move(TravelContent.Station s,BooleanSupplier valid){if(!safe(s))return CompletableFuture.completedFuture(false);return sessions.combatMove(player,session,new Location(player.getWorld(),s.arrival().x(),s.arrival().y(),s.arrival().z(),s.yaw(),s.pitch()),()->valid.getAsBoolean()&&safe(s));}
        public void release(){if(lease==null)return;var l=leases.get(lease);if(l!=null&&--l.count==0){leases.remove(lease);if(l.owned)l.chunk.removePluginChunkTicket(plugin);}lease=null;}
    }
    private boolean valid(Player p,Screen s){return !closed&&screens.get(p.getUniqueId())==s&&sessions.current(p)==s.port.session&&s.generation==s.port.generation()&&s.port.current()&&s.port.facility(content.get(s.source))&&s.port.position().distance(content.get(s.source).facility())<=16;}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void interact(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||e.getAction()!=Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null)return;var p=e.getPlayer();var s=sessions.current(p);if(s==null)return;var b=e.getClickedBlock();for(var station:content.stations().values())if(station.facility().x()==b.getX()&&station.facility().y()==b.getY()&&station.facility().z()==b.getZ()&&station.material().equals(b.getType().name())){e.setCancelled(true);open(p,s,station.id());return;}}
    private void open(Player p,PlayerSessions.Session session,String source){if(queries.containsKey(p.getUniqueId()))return;var port=new Port(p,session);if(!port.eligible()||!port.facility(content.get(source)))return;Object nonce=new Object();queries.put(p.getUniqueId(),nonce);long gen=port.generation();port.read().whenCompleteAsync((view,error)->{if(!queries.remove(p.getUniqueId(),nonce)||!port.current()||port.generation()!=gen)return;try{if(error!=null)throw new CompletionException(error);var choices=travel.destinations(view,port,source);var screen=new Screen(port,source,choices,0);screens.put(p.getUniqueId(),screen);p.openInventory(screen.inventory);}catch(RuntimeException failure){p.sendMessage(Component.text("거점 조회를 완료하지 못했습니다. 방문 해금과 접근 권한을 확인해 주세요."));}},owner);}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Screen s))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!valid(p,s)||s.busy||e.getClickedInventory()!=s.inventory||e.getClick()!=ClickType.LEFT)return;
        int selectedSlot=e.getSlot();String target=s.targets.get(selectedSlot);if(target==null&&(selectedSlot!=45&&selectedSlot!=53||!FastTravel.pageAvailable(s.choices.size(),s.page+(selectedSlot==45?-1:1))))return;s.busy=true;Bukkit.getScheduler().runTaskLater(plugin,()->{if(!valid(p,s)||p.getOpenInventory().getTopInventory()!=s.inventory)return;if(target==null){var next=new Screen(s.port,s.source,s.choices,s.page+(selectedSlot==45?-1:1));screens.put(p.getUniqueId(),next);p.openInventory(next.inventory);return;}p.closeInventory();ports.put(p.getUniqueId(),s.port);var task=travel.start(s.port,s.source,target,UUID.randomUUID());var timeout=Bukkit.getScheduler().runTaskLater(plugin,()->travel.cancel(s.port),200);task.whenCompleteAsync((v,error)->{timeout.cancel();if(s.port.current())p.sendMessage(Component.text(error==null?"거점 이동 완료":"거점 이동 거부 또는 보류 · 원본 저장 상태를 보존했습니다."));},owner);},1);}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Screen)e.setCancelled(true);}
    @EventHandler public void inventoryClosed(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof Screen s)screens.remove(e.getPlayer().getUniqueId(),s);}
    @EventHandler(priority=EventPriority.LOWEST) public void quit(PlayerQuitEvent e){queries.remove(e.getPlayer().getUniqueId());screens.remove(e.getPlayer().getUniqueId());var p=ports.remove(e.getPlayer().getUniqueId());if(p!=null){travel.cancel(p);travel.barrier(p.context().storyRunId()).whenCompleteAsync((v,error)->travel.forget(p),owner);}}
    public boolean settled(UUID run){return travel.settled(run);}
    public static Inventory previewDestinations(List<FastTravel.Destination> choices,int page){var inventory=Bukkit.createInventory(null,54,Component.text("시설 거점 이동"));int slot=0;for(var row:FastTravel.page(choices,page)){var item=new ItemStack(Material.COMPASS);item.editMeta(m->{m.displayName(Component.text(row.name()));m.lore(List.of(Component.text(row.location()),Component.text("본인이 직접 방문한 거점"),Component.text("비용/운영 소요 시간은 미정 · 격리 이동 시험")));});inventory.setItem(slot++,item);}return inventory;}
    public CompletionStage<Void> barrier(UUID run){return travel.barrier(run);}
    public void close(){main();if(closed)return;closed=true;travel.close();sessions.travelInventory((p,i)->false);HandlerList.unregisterAll(this);screens.clear();queries.clear();ports.clear();}
}
